package com.pianoquest.app.data

/** One page of a composer's storybook. [image] is a LessonImages key; [songId] adds a "Hear it" button. */
data class StoryPage(val title: String, val year: String, val text: String, val image: String? = null, val songId: String? = null)

/** A quiz question at the end of a storybook: the first option is correct. */
data class StoryQuiz(val question: String, val options: List<String>)

data class Composer(
    val id: String,
    val name: String,
    val fullName: String,
    val years: String,
    val country: String,
    val era: String,
    /** LessonImages key of the portrait, or null for a drawn monogram. */
    val portrait: String?,
    val tagline: String,
    /** Song-library composer strings that belong to this composer. */
    val match: List<String>,
    val story: List<StoryPage>,
    val quiz: List<StoryQuiz>,
) {
    val songs: List<Song> by lazy { Popularity.sort(SongLibrary.all.filter { s -> match.any { s.composer.contains(it) } }) }
    val initials: String get() = name.split(' ').filter { it.isNotEmpty() }.takeLast(1).joinToString("") { it.take(1) }
}

private fun q(question: String, vararg options: String) = StoryQuiz(question, options.toList())

